""" Calculates the incremental mean different batch sizes
    Args:
        float:
            xbarj mean of all previous
        float:
            Nj number of planets in all previous batches
        ndarray:
            xbarm mean of values in current batch
        float:
            Nm number of elements in current batch
    """
def incremental_mean_differentSizeBatches(
    xbarj: Any, Nj: Any, xbarm: Any, Nm: Any
) -> object {
    xbarjp1 = ((Nj * xbarj) + (Nm * xbarm)) / (Nj + Nm);
    return xbarjp1;
}

"""Generate matrices benchmarking parameters.

    Parameters
    ----------
    n_samples : int
        Number of samples to be used.

    Returns
    -------
    _ : list.
        List of params.
    """
def matrices_params(n_samples: Any) -> object {
    manifold = "Matrices";
    manifold_args = [(3, 3), (5, 5)];
    module = "geomstats.geometry.matrices";
    def matrices_metric_params() -> object {
        params = [];
        metric = "MatricesMetric";
        metric_args = manifold_args;
        kwargs = {};
        common = (manifold, module, metric, n_samples, kwargs);
        for (manifold_arg, metric_arg) in zip(manifold_args, metric_args) {
            params += [(common + (manifold_arg, metric_arg))];
        }
        return params;
    }
    return matrices_metric_params();
}

"""
	Alpha function: determines extent to which node matrix is altered over time
	Exponential function with half life of 160 iterations
	"""
def alpha_fixed(s: int) -> float {
    alpha_val = 0.5 * (2 ** (-s / 240));
    return alpha_val;
}

"""
    Get axis limit

    Parameters
    ----------
    ax_min : float
    ax_max : float
    base : int, default = 10

    Returns
    -------
    ax_min : float
    ax_max : float
    """
def get_ax_lim(ax_min: Any, ax_max: Any, base: Any = 10) -> object {
    import from math { ceil, floor }
    ax_min = floor((ax_min * base)) / base;
    ax_max = ceil((ax_max * base)) / base;
    return (ax_min, ax_max);
}

"""
    A hack to add basic surrogate
    pair support for SMP Unicode characters
    when using a build which isn't wide.
    Seems to (at least partially) work!
    """
def w_unichr(s: Any) -> object {
    try {
        return chr(s);
    } except Exception as e {
        if not s {
            raise;
        }
        hex_val = str(hex(int(s)))[2:];
        result = '0' * (8 - len(hex_val));
        s = 'Fix PyDev Lexer!';
        exec_ = "s = '\\U%s%s'" % (result, hex_val);
        exec(exec_);
        return s;
    }
}

"""Clean up a multiline description."""
